def mock_claude(messages, call_count):
    if call_count < 2:
        return {
            "stop_reason": "tool_use",
            "content": [
                {"type": "tool_use", "id": f"t{call_count}",
                 "name": "add", "input": {"a": call_count * 10, "b": 5}}
            ]
        }
    return {"stop_reason": "end_turn", "content": [{"type": "text", "text": "완료"}]}

messages = []
call_count = 0
tool_results = []

while True:
    response = mock_claude(messages, call_count)
    call_count += 1

    if response["stop_reason"] == "end_turn":
        break

    for blk in response["content"]:
        if blk["type"] == "tool_use":
            result = blk["input"]["a"] + blk["input"]["b"]
            tool_results.append(result)

print(tool_results)
print(call_count)
```

