def build_tool(name, description, params):
    properties = {}
    required = []
    for param_name, param_type, is_required in params:
        properties[param_name] = {"type": param_type}
        if is_required:
            required.append(param_name)
    return {
        "name": name,
        "description": description,
        "input_schema": {
            "type": "object",
            "properties": properties,
            "required": required
        }
    }

tool = build_tool(
