def validate_tool_input(tool_schema, user_input):
    required   = tool_schema.get("required", [])
    properties = tool_schema.get("properties", {})
    missing      = [r for r in required if r not in user_input]
    invalid_keys = [k for k in user_input if k not in properties]
    return len(missing), len(invalid_keys)

schema = {
    "type": "object",
    "properties": {
        "city": {"type": "string"},
        "unit": {"type": "string"},
        "days": {"type": "integer"}
    },
    "required": ["city"]
}

missing, invalid = validate_tool_input(
    schema, {"city": "서울", "unknown_param": "test"}
)
print(missing)
print(invalid)
```

