def comprehensive_agent(query, tool_plan, max_iter=5):
    history = [{"role": "user", "content": query}]
    completed_tools = []
    iteration = 0
    for tool_name, should_error in tool_plan:
        if iteration >= max_iter:
            break
        iteration += 1
        history.append({"role": "assistant", "content": f"calling:{tool_name}"})
        if should_error:
            result = {"type": "tool_result", "is_error": True,  "content": f"오류:{tool_name}"}
        else:
            result = {"type": "tool_result", "is_error": False, "content": f"성공:{tool_name}"}
            completed_tools.append(tool_name)
        history.append({"role": "user", "content": [result]})
    history.append({"role": "assistant", "content": "최종답변"})
    return len(history), len(completed_tools), iteration

print(comprehensive_agent(
    "여행 계획 짜줘",
    [("search", False), ("weather", True), ("translate", False)],
    max_iter=5
))
